/* ============================================================
   PATCH 1.0.14 — Автообновление в меню пользователя (стабильное)
   ============================================================ */
(function(){
'use strict';
if (window.__trkAutoUpdateMenuV114) return;
window.__trkAutoUpdateMenuV114 = true;

var _cbMenu = document.getElementById('udAutoUpdate');
if (!_cbMenu) return;

function _getCSRF() {
    var csrf = window.REESTR_CSRF || '';
    if (!csrf) {
        var meta = document.querySelector('meta[name="csrf-token"]');
        if (meta) csrf = meta.getAttribute('content') || '';
    }
    return csrf;
}

function _notify(msg, kind) {
    if (typeof window.__trackerNotify === 'function') {
        try { window.__trackerNotify(msg, kind); return; } catch(e){}
    }
    if (typeof window.__settingsNotify === 'function') {
        try { window.__settingsNotify(msg, kind); return; } catch(e){}
    }
    console.warn(msg);
}

function _syncBoth(val) {
    _cbMenu.checked = val;
    var cbModal = document.getElementById('trkUpdateAuto');
    if (cbModal) cbModal.checked = val;
}

function _load() {
    fetch('/api/plugins/updater/settings', {credentials: 'same-origin'})
        .then(function(r) {
            var ct = r.headers.get('content-type') || '';
            if (ct.indexOf('application/json') === -1) throw new Error('Ожидался JSON, получен ' + ct);
            return r.json();
        })
        .then(function(d) {
            if (d && d.success) {
                _syncBoth(!!d.auto_update);
                _cbMenu.disabled = false;
            } else {
                _notify('❌ Ошибка загрузки настроек автообновления: ' + (d.error || '?'), 'error');
            }
        })
        .catch(function(e) {
            _notify('❌ Ошибка соединения: ' + e.message, 'error');
        });
}

function _save(val) {
    _cbMenu.disabled = true;
    var csrf = _getCSRF();
    var hdrs = {'Content-Type': 'application/json'};
    if (csrf) hdrs['X-CSRF-Token'] = csrf;

    fetch('/api/plugins/updater/settings', {
        method: 'POST', credentials: 'same-origin', headers: hdrs,
        body: JSON.stringify({auto_update: val})
    })
    .then(function(r) {
        var ct = r.headers.get('content-type') || '';
        if (ct.indexOf('application/json') === -1) throw new Error('HTTP ' + r.status);
        return r.json();
    })
    .then(function(d) {
        _cbMenu.disabled = false;
        if (d && d.success) {
            _syncBoth(!!d.auto_update);
            _notify(val ? '✅ Автообновление включено' : '⏸ Автообновление выключено');
        } else {
            _notify('❌ Не удалось сохранить: ' + (d.error || '?'), 'error');
            _syncBoth(!val);
        }
    })
    .catch(function(e) {
        _cbMenu.disabled = false;
        _notify('❌ Ошибка сохранения: ' + e.message, 'error');
        _syncBoth(!val);
    });
}

_cbMenu.addEventListener('change', function(e) {
    e.stopPropagation();
    _save(this.checked);
});

_cbMenu.addEventListener('click', function(e) { e.stopPropagation(); });

var wrap = document.getElementById('udAutoUpdateWrap');
if (wrap) {
    wrap.addEventListener('click', function(e) {
        if (e.target !== _cbMenu) {
            e.preventDefault();
            e.stopPropagation();
            if (!_cbMenu.disabled) {
                _cbMenu.checked = !_cbMenu.checked;
                _save(_cbMenu.checked);
            }
        }
    });
}

document.addEventListener('change', function(e) {
    if (e.target && e.target.id === 'trkUpdateAuto') {
        _syncBoth(e.target.checked);
    }
});

_load();
})();
